mapper.select:
SELECT * FROM EQUITY_STRUCTURE
WHERE INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
ORDER BY SHAREHOLDING_RATIO DESC

SELECT * FROM EQUITY_STRUCTURE
WHERE INVESTOR_ENTERPRISE_ID = #{investorEnterpriseId}
ORDER BY SHAREHOLDING_RATIO DESC

select.if:
WITH RECURSIVE equity_tree AS (
    SELECT *, 1 as level FROM EQUITY_STRUCTURE
    WHERE INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
    UNION ALL
    SELECT e.*, et.level + 1 FROM EQUITY_STRUCTURE e
    INNER JOIN equity_tree et ON e.INVESTEE_ENTERPRISE_ID = et.INVESTOR_ENTERPRISE_ID
    WHERE et.level < #{maxLevel}
)
SELECT * FROM equity_tree ORDER BY level, SHAREHOLDING_RATIO DESC

SELECT * FROM EQUITY_STRUCTURE
WHERE INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
ORDER BY SHAREHOLDING_RATIO DESC

WITH RECURSIVE equity_tree AS (
    SELECT *, 1 as level FROM EQUITY_STRUCTURE
    WHERE INVESTOR_ENTERPRISE_ID = #{investorEnterpriseId}
    UNION ALL
    SELECT e.*, et.level + 1 FROM EQUITY_STRUCTURE e
    INNER JOIN equity_tree et ON e.INVESTOR_ENTERPRISE_ID = et.INVESTEE_ENTERPRISE_ID
    WHERE et.level < #{maxLevel}
)
SELECT * FROM equity_tree ORDER BY level, SHAREHOLDING_RATIO DESC

SELECT * FROM EQUITY_STRUCTURE
WHERE INVESTOR_ENTERPRISE_ID = #{investorEnterpriseId}
ORDER BY SHAREHOLDING_RATIO DESC

mapper.select:
SELECT COALESCE(SUM(INDIRECT_SHAREHOLDING_RATIO), 0) as indirectRatio
FROM EQUITY_STRUCTURE
WHERE INVESTOR_ENTERPRISE_ID = #{investorEnterpriseId}
AND INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
AND INVESTMENT_LEVEL > 1

SELECT COALESCE(SUM(TOTAL_SHAREHOLDING_RATIO), 0) as totalRatio
FROM EQUITY_STRUCTURE
WHERE INVESTOR_ENTERPRISE_ID = #{investorEnterpriseId}
AND INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}

SELECT
DATE_FORMAT(INVESTMENT_DATE, '%Y-%m') as period,
TO_CHAR(INVESTMENT_DATE, 'YYYY-MM') as period,
COUNT(*) as count, SUM(INVESTMENT_AMOUNT) as totalAmount, AVG(SHAREHOLDING_RATIO) as avgRatio FROM EQUITY_STRUCTURE WHERE INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
AND INVESTMENT_DATE >= #{startDate}
AND INVESTMENT_DATE <= #{endDate}
GROUP BY
DATE_FORMAT(INVESTMENT_DATE, '%Y-%m')
TO_CHAR(INVESTMENT_DATE, 'YYYY-MM')
ORDER BY period

mapper.delete:
DELETE FROM EQUITY_STRUCTURE WHERE EQUITY_STATUS = 'CANCELLED' AND UPDATE_TIME <
DATE_SUB(NOW(), INTERVAL #{days} DAY)
SYSDATE - #{days}
